package com.shopstream.catalog;

import java.math.BigDecimal;
import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.CachePut;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

record ProductDto(long id, String name, BigDecimal price) {}

@Service
public class ProductService {

    private final ProductRepository repository;

    public ProductService(ProductRepository repository) {
        this.repository = repository;
    }

    @Cacheable(cacheNames = "products", key = "#id", unless = "#result == null")
    public ProductDto findById(long id) {
        return repository.load(id);
    }

    @CachePut(cacheNames = "products", key = "#result.id()")
    public ProductDto update(ProductDto changed) {
        return repository.save(changed);
    }

    @CacheEvict(cacheNames = "products", key = "#id")
    public void delete(long id) {
        repository.delete(id);
    }

    @CacheEvict(cacheNames = "products", allEntries = true)
    public void clearAll() {
    }
}

interface ProductRepository {
    ProductDto load(long id);
    ProductDto save(ProductDto dto);
    void delete(long id);
}

package com.shopstream.catalog;

import java.time.Duration;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.cache.BatchStrategies;
import org.springframework.data.redis.cache.RedisCacheConfiguration;
import org.springframework.data.redis.cache.RedisCacheManager;
import org.springframework.data.redis.cache.RedisCacheWriter;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.serializer.JacksonJsonRedisSerializer;
import org.springframework.data.redis.serializer.RedisSerializationContext.SerializationPair;
import org.springframework.data.redis.serializer.StringRedisSerializer;

@Configuration
@EnableCaching
public class RedisCacheConfig {

    @Bean
    RedisCacheManager cacheManager(RedisConnectionFactory factory) {
        RedisCacheWriter writer =
            RedisCacheWriter.nonLockingRedisCacheWriter(factory, BatchStrategies.scan(1000));

        RedisCacheConfiguration defaults = RedisCacheConfiguration.defaultCacheConfig()
            .entryTtl(Duration.ofMinutes(10))
            .disableCachingNullValues()
            .prefixCacheNameWith("shopstream:")
            .serializeKeysWith(SerializationPair.fromSerializer(StringRedisSerializer.UTF_8));

        RedisCacheConfiguration products = defaults
            .entryTtl((key, value) -> Duration.ofMinutes(30)
                .plusSeconds(ThreadLocalRandom.current().nextLong(0, 300)))
            .serializeValuesWith(SerializationPair.fromSerializer(
                new JacksonJsonRedisSerializer<>(ProductDto.class)));

        RedisCacheConfiguration stockView = defaults
            .entryTtl(Duration.ofMinutes(1));

        return RedisCacheManager.builder(writer)
            .cacheDefaults(defaults)
            .withInitialCacheConfigurations(Map.of(
                "products", products,
                "stock-view", stockView))
            .enableStatistics()
            .build();
    }
}

